package com.brokerage.invest.plans;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.test.web.servlet.MockMvc;

// Contract tests generated by Tester from recurring-investments.yaml v1.2.0
@WebMvcTest(PlanController.class)
class PlanContractTest {

  @Autowired MockMvc mvc;

  static final String BODY = """
      { "accountId": "acc_1029", "amount": 250.00,
        "frequency": "MONTHLY", "startDate": "2026-12-01" }
      """;

  @Test
  void createPlan_returns201WithLocation() throws Exception {
    mvc.perform(post("/v1/plans").header("Idempotency-Key", "k-001")
            .contentType("application/json").content(BODY))
        .andExpect(status().isCreated())
        .andExpect(header().exists("Location"));
  }

  @Test
  void createPlan_reusedKey_returns409() throws Exception {
    mvc.perform(post("/v1/plans").header("Idempotency-Key", "k-002")
        .contentType("application/json").content(BODY));
    mvc.perform(post("/v1/plans").header("Idempotency-Key", "k-002")
            .contentType("application/json").content(BODY))
        .andExpect(status().isConflict());
  }

  @Test
  void createPlan_missingKey_returns400() throws Exception {
    mvc.perform(post("/v1/plans").contentType("application/json").content(BODY))
        .andExpect(status().isBadRequest());
  }

  @Test
  void listPlans_returnsPlansForAccount() throws Exception {
    mvc.perform(get("/v1/plans").param("accountId", "acc_1029"))
        .andExpect(status().isOk());
  }

  @Test
  void updatePlanStatus_pausesActivePlan() throws Exception {
    mvc.perform(patch("/v1/plans/pl_77/status")
            .contentType("application/json").content("{ \"status\": \"PAUSED\" }"))
        .andExpect(status().isOk());
  }
}
